import React, { useState, useEffect } from 'react';
import axios from 'axios';
import PiePagina from '../Componentes/PiePagina';

function Inicio() {
  const [perrosAPI, setPerrosAPI] = useState([]);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    // Consumir API pública Dog CEO (public-apis)
    axios
      .get('https://dog.ceo/api/breeds/image/random/6')
      .then((respuesta) => {
        setPerrosAPI(respuesta.data.message);
        setCargando(false);
      })
      .catch((error) => {
        console.error('Error al consumir la API pública:', error);
        setCargando(false);
      });
  }, []);

  return (
    <>
      <main className="contenedor">
        <h2 className="titulo-seccion">Bienvenidos a Huellitas de Amor</h2>
        <p className="descripcion-seccion">
          Somos una organización dedicada al rescate, rehabilitación y adopción responsable de perros y gatos. ¡Encuentra a tu nuevo mejor amigo hoy!
        </p>

        <h3 style={{ color: '#2c3e50', marginBottom: '1rem' }}>
          🐶 Fotos Destacadas de la Red (Datos en tiempo real mediante API pública)
        </h3>

        {cargando ? (
          <div className="cargando">Cargando fotografías desde la API...</div>
        ) : (
          <div className="grid-tarjetas">
            {perrosAPI.map((urlImagen, index) => (
              <div key={index} className="tarjeta">
                <img src={urlImagen} alt={`Perro rescatado ${index + 1}`} />
                <div className="tarjeta-contenido">
                  <h3>Candidato a Adopción #{index + 1}</h3>
                  <span className="badge">Fotografía de API Pública</span>
                  <p>Hermoso ejemplar buscando un hogar lleno de amor. Vacunas al día y desparasitado.</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
      <PiePagina />
    </>
  );
}

export default Inicio;
